questionvariables.text:
/*Defining the question variables*/
coef_w:(rand_with_step(1,20,2))/2;
coef_func:rand(10)+1;
func_w:coef_func*((cos(coef_w*w))^3*(sin(coef_w*w))^5);
lower_limit: rand([0, %pi, 2*%pi, 3*%pi, 4*%pi]); 
upper: rand([%pi, 2*%pi, 3*%pi/2, (4/3*%pi), (4*%pi), 12*%pi]); 
upper_limit: if lower_limit < upper then upper else rand([%pi, 2*%pi, 3*%pi/2, (4/3*%pi), (4*%pi),12*%pi]); 
upper_limit:upper_limit+%pi;

recal: cos(u)^2=1-sin(u)^2;
/*model answer*/
expr: -((1/coef_w*coef_func)/8)*sin((coef_w)*w)^8+((1/coef_w*coef_func)/6)*sin((coef_w)*w)^6+c;
expr1: ev(expr,w=lower_limit),simp;
expr2: ev(expr,w=upper_limit),simp;
ta:ev(expr2-expr1),simp;



/*Node 1 checks for correct answer*/
/*Node 2: mistake_ computing indefinite integral and adding the constant after integration*/
mistake_2: int(func_w,w)+c;
/*Node 3: mistake_  Interchanging the limits of integration, with the correct integral */
mistake_3: int(func_w,w,upper_limit,lower_limit); 
/*Node 4: mistake_  computing definite integral correctly but adding a constant */
mistake_4: int(func_w,w,lower_limit,upper_limit)+c;
